]

# 3x3 majority rule
def apply_rule_3x3(grid):
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 7:
                # Get 3x3 window
                win_vals = []
                for di in range(-1, 2):
                    for dj in range(-1, 2):
                        ni, nj = i + di, j + dj
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if grid[ni][nj] not in result or not result[ni][nj]:
                                win_vals.append(grid[ni][nj])
                        else:
                            win_vals.append(grid[ni][nj])

                # Find most common (break ties by preferring existing 7 position value)
                counts = {}
                for v in win_vals:
                    counts[v] = counts.get(v, 0) + 1
                max_c = max(counts.values())
                candidates = [v for v, c in counts.items() if c == max_c]
                # Prefer longer-appearing/position-based tiebreaker
                result[i][j] = candidates[0] if len(candidates) == 1 else candidates[0]

    return result

